ash8", "name": "Splash 8", "source": "Splash8.html", "sourceSha256": "0476030ae8f2a28996e7f2a86a5706e753b250b30ab43f50f55e936da68d8d7c", "skills": [{"id": "Splash8:1", "number": "1", "name": "Demonstrate 1 Forward And 1 Backward Somersault in the Water as a Continuous Sequence", "sourceLines": ["\u2022 Complete \"head over heels rotation\" with control of direction", "\u2022 Somersaults performed as a continuous sequence"], "subskills": [{"id": "Splash8:1:1", "text": "Complete \"head over heels rotation\" with control of direction", "group": []}, {"id": "Splash8:1:2", "text": "Somersaults performed as a continuous sequence", "group": []}]}, {"id": "Splash8:2", "number": "2", "name": "Stride Entry and Swim 25 m or yd Head-up Front Crawl or Breaststroke. Assume Ready Position", "sourceLines": ["\u2022 Eyes above surface", "\u2022 Basic arm and leg mechanics", "\u2022 Distance completed non-stop", "\u2022 Ready position"], "subskills": [{"id": "Splash8:2:1", "text": "Eyes above surface", "group": []}, {"id": "Splash8:2:2", "text": "Basic arm and leg mechanics", "group": []}, {"id": "Splash8:2:3", "text": "Distance completed non-stop", "group": []}, {"id": "Splash8:2:4", "text": "Ready position", "group": []}]}, {"id": "Splash8:3", "number": "3", "name": "Demonstrate 25 m or yd Eggbeater Kick on Back", "sourceLines": ["\u2022 Movement pattern of kick resembles whip kick with alternate leg action", "\u2022 Drive with knees apart; feet wider than knees", "\u2022 Distance completed"], "subskills": [{"id": "Splash8:3:1", "text": "Movement pattern of kick resembles whip kick with alternate leg action", "group": []}, {"id": "Splash8:3:2", "text": "Drive with knees apart; feet wider than knees", "group": []}, {"id": "Splash8:3:3", "text": "Distance completed", "group": []}]}, {"id": "Splash8:4", "number": "4", "name": "Support a 2.3 kg (5 lb) Object for at Least 1 min. in Deep Water", "sourceLines": ["\u2022 Head above surface throughout", "\u2022 Time met or bettered"], "subs